UPDATE lessons SET content = $lsn${"steps": [{"step_type": "intro", "title": "Today's Goal", "instruction": "Let's learn how to say what you want to do using 고 싶어요.", "content": {"explanation": {"title": "I want to ..."}, "sentences": [{"korean": "저는 커피를 마시고 싶어요.", "english": "I want to drink coffee.", "tts": true, "chunks": [{"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "마시고", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요.", "tokens": [{"text": "싶어요", "meaning": "want to"}]}]}, {"korean": "저는 책을 읽고 싶어요.", "english": "I want to read a book.", "tts": true, "chunks": [{"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "책을", "tokens": [{"text": "책", "meaning": "book"}, {"text": "을", "meaning": "object marker"}]}, {"display": "읽고", "tokens": [{"text": "읽", "meaning": "read"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요.", "tokens": [{"text": "싶어요", "meaning": "want to"}]}]}]}}, {"step_type": "intro", "title": "Conversation #1", "instruction": "Listen to Minsu and Yumi talk about what they want to do.", "content": {"explanation": {"title": "What do you want to do?"}, "sentences": [{"korean": "유미: 민수 씨, 오늘 뭐 하고 싶어요?", "english": "Yumi: Minsu, what do you want to do today?", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "민수", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}]}, {"display": "씨,", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}]}, {"display": "오늘", "tokens": [{"text": "오늘", "meaning": "today"}]}, {"display": "뭐", "tokens": [{"text": "뭐", "meaning": "what"}]}, {"display": "하고", "tokens": [{"text": "하", "meaning": "do"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요?", "tokens": [{"text": "싶어요", "meaning": "want to"}]}]}, {"korean": "민수: 저는 카페에 가고 싶어요. 커피를 마시고 싶어요.", "english": "Minsu: I want to go to a café. I want to drink coffee.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "카페에", "tokens": [{"text": "카페", "meaning": "café"}, {"text": "에", "meaning": "place marker"}]}, {"display": "가고", "tokens": [{"text": "가", "meaning": "go"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요.", "tokens": [{"text": "싶어요", "meaning": "want to"}]}, {"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "마시고", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요.", "tokens": [{"text": "싶어요", "meaning": "want to"}]}]}, {"korean": "유미: 저는 커피를 안 마셔요. 밥을 먹고 싶어요.", "english": "Yumi: I don't drink coffee. I want to eat.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "안", "tokens": [{"text": "안", "meaning": "not"}]}, {"display": "마셔요.", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "밥을", "tokens": [{"text": "밥", "meaning": "rice / meal"}, {"text": "을", "meaning": "object marker"}]}, {"display": "먹고", "tokens": [{"text": "먹", "meaning": "eat"}, {"text": "고", "meaning": "and (link)"}]}, {"display": "싶어요.", "tokens": [{"text": "싶어요", "meaning": "want to"}]}]}, {"korean": "민수: 아, 그래요? 식당에 가고 싶어요?", "english": "Minsu: Oh, really? Do you want to go to a restaurant?", "tts": true, 