UPDATE lessons SET content = $lsn${"steps": [{"step_type": "intro", "title": "Today's Goal", "instruction": "Let's learn how to ask someone politely to do something using (으)세요.", "content": {"explanation": {"title": "Please ..."}, "sentences": [{"korean": "여기에 앉으세요.", "english": "Please sit here.", "tts": true, "chunks": [{"display": "여기에", "tokens": [{"text": "여기", "meaning": "here"}, {"text": "에", "meaning": "place marker"}]}, {"display": "앉으세요.", "tokens": [{"text": "앉", "meaning": "sit"}, {"text": "으세요", "meaning": "please (polite)"}]}]}, {"korean": "물을 마시세요.", "english": "Please drink water.", "tts": true, "chunks": [{"display": "물을", "tokens": [{"text": "물", "meaning": "water"}, {"text": "을", "meaning": "object marker"}]}, {"display": "마시세요.", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "세요", "meaning": "please (polite)"}]}]}]}}, {"step_type": "intro", "title": "Conversation #1", "instruction": "Listen to Minsu and Yumi at a café.", "content": {"explanation": {"title": "Please sit here"}, "sentences": [{"korean": "민수: 유미 씨, 여기에 앉으세요.", "english": "Minsu: Yumi, please sit here.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "유미", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}]}, {"display": "씨,", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}]}, {"display": "여기에", "tokens": [{"text": "여기", "meaning": "here"}, {"text": "에", "meaning": "place marker"}]}, {"display": "앉으세요.", "tokens": [{"text": "앉", "meaning": "sit"}, {"text": "으세요", "meaning": "please (polite)"}]}]}, {"korean": "유미: 네. 아, 제 가방이 없어요.", "english": "Yumi: Okay. Ah, my bag isn't here.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "네.", "tokens": [{"text": "네", "meaning": "yes"}]}, {"display": "아,", "tokens": [{"text": "아", "meaning": "Ah"}]}, {"display": "제", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "의", "meaning": "possessive marker"}]}, {"display": "가방이", "tokens": [{"text": "가방", "meaning": "bag"}, {"text": "이", "meaning": "subject marker"}]}, {"display": "없어요.", "tokens": [{"text": "없", "meaning": "there isn't / don't have"}, {"text": "어요", "meaning": "polite ending"}]}]}, {"korean": "민수: 가방을 찾으세요. 저는 여기에 있어요.", "english": "Minsu: Please look for your bag. I'll be here.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "가방을", "tokens": [{"text": "가방", "meaning": "bag"}, {"text": "을", "meaning": "object marker"}]}, {"display": "찾으세요.", "tokens": [{"text": "찾", "meaning": "look for / find"}, {"text": "으세요", "meaning": "please (polite)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "여기에", "tokens": [{"text": "여기", "meaning": "here"}, {"text": "에", "meaning": "place marker"}]}, {"display": "있어요.", "tokens": [{"text": "있", "meaning": "there is / have / be at"}, {"text": "어요", "meaning": "polite ending"}]}]}, {"korean": "유미: 아, 여기 있어요!", "english": "Yumi: Oh, here it is!", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "아,", "tokens": [{"text": "아", "meaning": "Ah"}]}, {"display": "여기", "tokens": [{"text": "여기", "meaning": "here"}]}, {"display": "있어요!", "tokens": [{"text": "있", "meaning": "there is / have / be at"}, {"text": "어요", "meaning": "polite ending"}]}]}]}}, {"step_type": "intro", "title": "Grammar: (으)세요", "instruction": "Use (으)세요 to ask someone politely to do something.", "content": {"explanation": {"title": "Consonant vs Vowel ending", "patterns": [{"pattern": "으세요 / 세요", "level": "Essential", "usage": "It asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}]}, "sentences": [{"korean": "읽으세요 = please read", "english": "읽 (ends with consonant ㄺ) + 으세요", "tts": false, "chunks": [{"display": "읽으세요", "tokens": [{"text": "읽", "meaning": "read"}, {"text": "으세요", "meaning": "please (polite)"}]}, {"display": "=", "tokens": []}, {"display": "please", "tokens": []}, {"display": "read", "tokens": []}]}, {"korean": "앉으세요 = please sit", "english": "앉 (ends with consonant ㄵ) + 으세요", "tts": false, "chunks": [{"display": "앉으세요", "tokens": [{"text": "앉", "meaning": "sit"}, {"text": "으세요", "meaning": "please (polite)"}]}, {"display": "=", "tokens": []}, {"display": "please", "tokens": []}, {"display": "sit", "tokens": []}]}, {"korean": "찾으세요 = please look for", "english": "찾 (ends with consonant ㅈ) + 으세요", "tts": false, "chunks": [{"display": "찾으세요", "tokens": [{"text": "찾", "meaning": "look for / find"}, {"text": "으세요", "meaning": "please (polite)"}]}, {"display": "=", "tokens": []}, {"display": "please", "tokens": []}, {"display": "look", "tokens": []}, {"display": "for", "tokens": []}]}, {"korean": "마시세요 = please drink", "english": "마시 (ends with vowel ㅣ) + 세요", "tts": false, "chunks": [{"display": "마시세요", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "세요", "meaning": "please (polite)"}]}, {"display": "=", "tokens": []}, {"display": "please", "tokens": []}, {"display": "drink", "tokens": []}]}, {"korean": "학교에 가세요 = please go to school", "english": "가 (ends with vowel ㅏ) + 세요", "tts": false, "chunks": [{"display": "학교에", "tokens": [{"text": "학교", "meaning": "school"}, {"text": "에", "meaning": "place marker"}]}, {"display": "가세요", "tokens": [{"text": "가", "meaning": "go"}, {"text": "세요", "meaning": "please (polite)"}]}, {"display": "=", "tokens": []}, {"display": "please", "tokens": []}, {"display": "go", "tokens": []}, {"display": "to", "tokens": []}, {"display": "school", "tokens": []}]}]}}, {"step_type": "practice", "title": "Pattern Practice", "instruction": "Choose the right answer.", "content": {"exercises": [{"type": "fill_blank", "instruction": "Please read the book.", "sentence": "책을 [ ? ].", "options": ["읽으세요", "읽세요"], "answer": "읽으세요", "feedback": {"correct": "Correct! 읽 ends in a consonant, so + 으세요"}}, {"type": "fill_blank", "instruction": "Please sit here.", "sentence": "여기에 [ ? ].", "options": ["앉세요", "앉으세요"], "answer": "앉으세요", "feedback": {"correct": "Right! 앉 ends in a consonant, so + 으세요"}}, {"type": "fill_blank", "instruction": "Please drink water.", "sentence": "물을 [ ? ].", "options": ["마시세요", "마시으세요"], "answer": "마시세요", "feedback": {"correct": "Great! 마시 ends in a vowel, so + 세요"}}, {"type": "fill_blank", "instruction": "Please go to school.", "sentence": "학교에 [ ? ].", "options": ["가으세요", "가세요"], "answer": "가세요", "feedback": {"correct": "Perfect! 가 ends in a vowel, so + 세요"}}, {"type": "fill_blank", "instruction": "Please look for the bag.", "sentence": "가방을 [ ? ].", "options": ["찾으세요", "찾세요"], "answer": "찾으세요", "feedback": {"correct": "Correct! 찾 ends in a consonant, so + 으세요"}}, {"type": "fill_blank", "instruction": "Please go to the library.", "sentence": "도서관에 가 [ ? ].", "options": ["으세요", "세요"], "answer": "세요", "feedback": {"correct": "Right! 가 ends in a vowel, so + 세요"}}]}}, {"step_type": "intro", "title": "Vocabulary: Please ...", "instruction": "Polite requests you can use.", "content": {"explanation": {"title": "Useful words"}, "sentences": [{"korean": "여기", "english": "Here", "tts": true, "chunks": [{"display": "여기", "tokens": [{"text": "여기", "meaning": "here"}]}]}, {"korean": "앉으세요", "english": "Please sit", "tts": true, "chunks": [{"display": "앉으세요", "tokens": [{"text": "앉으세요", "meaning": "please sit"}]}]}, {"korean": "찾으세요", "english": "Please look for", "tts": true, "chunks": [{"display": "찾으세요", "tokens": [{"text": "찾으세요", "meaning": "please look for"}]}]}, {"korean": "읽으세요", "english": "Please read", "tts": true, "chunks": [{"display": "읽으세요", "tokens": [{"text": "읽으세요", "meaning": "please read"}]}]}, {"korean": "마시세요", "english": "Please drink", "tts": true, "chunks": [{"display": "마시세요", "tokens": [{"text": "마시세요", "meaning": "please drink"}]}]}, {"korean": "가세요", "english": "Please go", "tts": true, "chunks": [{"display": "가세요", "tokens": [{"text": "가세요", "meaning": "please go"}]}]}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"Please read the book.\" Split the verb and (으)세요.", "contentObj": {"sentence": "책을 읽으세요.", "translation": "Please read the book.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["책을"], "correct_turtle": ["책을"], "turtle_explanation": "Keep '책을' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["읽으세요"], "correct_turtle": ["읽", "으세요"], "turtle_explanation": "'으세요' asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}], "options": [{"id": "o1", "text": "세요", "mode": "turtle"}, {"id": "o2", "text": "책을", "mode": "turtle"}, {"id": "o3", "text": "으세요", "mode": "turtle"}, {"id": "o4", "text": "책을", "mode": "rabbit"}, {"id": "o5", "text": "읽", "mode": "turtle"}, {"id": "o6", "text": "읽으세요", "mode": "rabbit"}, {"id": "o7", "text": "읽세요", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Please sit here.\" Split the verb and (으)세요.", "contentObj": {"sentence": "여기에 앉으세요.", "translation": "Please sit here.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["여기에"], "correct_turtle": ["여기에"], "turtle_explanation": "Keep '여기에' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["앉으세요"], "correct_turtle": ["앉", "으세요"], "turtle_explanation": "'으세요' asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}], "options": [{"id": "o1", "text": "앉", "mode": "turtle"}, {"id": "o2", "text": "으세요", "mode": "turtle"}, {"id": "o3", "text": "세요", "mode": "turtle"}, {"id": "o4", "text": "앉으세요", "mode": "rabbit"}, {"id": "o5", "text": "여기에", "mode": "rabbit"}, {"id": "o6", "text": "앉세요", "mode": "rabbit"}, {"id": "o7", "text": "여기에", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #3", "instruction": "Build the sentence: \"Please drink water.\" Split the verb and (으)세요.", "contentObj": {"sentence": "물을 마시세요.", "translation": "Please drink water.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["물을"], "correct_turtle": ["물을"], "turtle_explanation": "Keep '물을' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["마시세요"], "correct_turtle": ["마시", "세요"], "turtle_explanation": "'세요' asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}], "options": [{"id": "o1", "text": "으세요", "mode": "turtle"}, {"id": "o2", "text": "마시", "mode": "turtle"}, {"id": "o3", "text": "마시세요", "mode": "rabbit"}, {"id": "o4", "text": "물을", "mode": "rabbit"}, {"id": "o5", "text": "세요", "mode": "turtle"}, {"id": "o6", "text": "마시으세요", "mode": "rabbit"}, {"id": "o7", "text": "물을", "mode": "turtle"}]}}, {"step_type": "completion", "title": "Lesson 4 Mastered!", "instruction": "Great! You can now ask someone politely to do something.", "content": {"text": "You've learned '[verb](으)세요.'\nConsonant ending → 으세요 (읽으세요), vowel ending → 세요 (마시세요).", "highlights": ["으세요", "세요"]}}]}$lsn$::jsonb
